static float Y[HOUT_MAX][WOUT_MAX];

void conv2d_rgb_inefficient(const float X[C][H][W], const float K[C][R][S],
                            float Y[HOUT_MAX][WOUT_MAX], int stride)
    {
        for (int i = 0; i < HOUT_MAX; i++)
            for (int j = 0; j < WOUT_MAX; j++)
                Y[i][j] = 0.0f;

        for (int i = 0; i < ((H - R) / stride + 1); i++) {
            for (int j = 0; j < ((W - S) / stride + 1); j++) {
                for (int c = 0; c < C; c++) {
                    for (int r = 0; r < R; r++) {
                        for (int s = 0; s < S; s++) {
                            int xi = i * stride + r;
                            int xj = j * stride + s;
                            Y[i][j] = Y[i][j] + X[c][xi][xj] * K[c][r][s];
                        }
                    }
                }
            }
        }

        int Hout = (H - R) / stride + 1;
        int Wout = (W - S) / stride + 1;
        for (int i = 0; i < Hout; i++) {
            for (int j = 0; j < Wout; j++) {
                printf("%.8f ", Y[i][j]);
            }
            printf("\n");
        }
    }

int main(void) {
    conv2d_rgb_inefficient(X, K, Y, 1);
    return 0;
}